import{_ as t,c as o,o as i,a2 as a}from"./chunks/framework.jqDK1qTK.js";const u=JSON.parse('{"title":"0018 Shoot Ca Rotation","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0018-shoot-ca-rotation","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0018-shoot-ca-rotation/README.md","to":"README.md"},"title":"0018 Shoot Ca Rotation","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0018-shoot-ca-rotation/index.md","filePath":"docs/proposals/0018-shoot-ca-rotation/index.md","lastUpdated":null}'),s={name:"docs/proposals/0018-shoot-ca-rotation/index.md"};function n(r,e,l,c,d,h){return i(),o("div",null,e[0]||(e[0]=[a(`<h1 id="gep-0018-automated-shoot-ca-rotation" tabindex="-1">GEP-0018: Automated Shoot CA Rotation <a class="header-anchor" href="#gep-0018-automated-shoot-ca-rotation" aria-label="Permalink to &quot;GEP-0018: Automated Shoot CA Rotation&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/docs/proposals/0018-shoot-ca-rotation/readme/#summary">Summary</a></li><li><a href="/docs/proposals/0018-shoot-ca-rotation/readme/#motivation">Motivation</a><ul><li><a href="/docs/proposals/0018-shoot-ca-rotation/readme/#goals">Goals</a></li><li><a href="/docs/proposals/0018-shoot-ca-rotation/readme/#non-goals">Non-Goals</a></li></ul></li><li><a href="/docs/proposals/0018-shoot-ca-rotation/readme/#proposal">Proposal</a></li><li><a href="/docs/proposals/0018-shoot-ca-rotation/readme/#alternatives">Alternatives</a></li><li><a href="/docs/proposals/0018-shoot-ca-rotation/readme/#open-questions">Open Questions</a></li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>This proposal outlines an on-demand, multi-step approach to rotate all certificate authorities (CA) used in a Shoot cluster. This process includes creating new CAs, invalidating the old ones and recreating all certificates signed by the CAs.</p><p>We propose to bundle the rotation of <em>all</em> CAs in the Shoot together as one triggerable action. This includes the recreation and invalidation of the following CAs and all certificates signed by them:</p><ul><li>Cluster CA (currently used for signing <code>kube-apiserver</code> serving certificates and client certificates)</li><li><code>kubelet</code> CA (used for signing client certificates for talking to <code>kubelet</code> API, e.g. <code>kube-apiserver-kubelet</code>)</li><li><code>etcd</code> CA (used for signing <code>etcd</code> serving certificates and client certificates)</li><li>front-proxy CA (used for signing client certificates that <code>kube-aggregator</code> (part of <code>kube-apiserver</code>) uses to talk to extension API servers, filled into <code>extension-apiserver-authentication</code> ConfigMap and read by extension API servers to verify incoming <code>kube-aggregator</code> requests)</li><li><code>metrics-server</code> CA (used for signing serving certificates, filled into APIService <code>caBundle</code> field and read by <code>kube-aggregator</code> to verify the presented serving certificate)</li><li><code>ReversedVPN</code> CA (used for signing <code>vpn-seed-server</code> serving certificate and <code>vpn-shoot</code> client certificate)</li></ul><p>Out of scope for now:</p><ul><li><code>kubelet</code> serving CA is self-generated (valid for <code>1y</code>) and self-signed by <code>kubelet</code> on startup. <ul><li><code>kube-apiserver</code> does not seem to verify the presented serving certificate.</li><li><code>kubelet</code> can be configured to request serving certificate via CSR that can be verified by <code>kube-apiserver</code>, though, we consider this as a separate improvement outside of this GEP.</li></ul></li><li>Legacy VPN solution uses the cluster CA for both serving and client certificates. As the solution is soon to be dropped in favor of the new <code>ReversedVPN</code> solution, we don&#39;t intend to introduce a dedicated CA for this component. If <code>ReversedVPN</code> is disabled and the CA rotation is triggered, we make sure to propagate the cluster CA to the relevant places in the legacy VPN solution.</li></ul><p>Naturally, not all certificates used for communication with the <code>kube-apiserver</code> are under control of Gardener. An example for a Gardener-controlled certificate is the kubelet client certificate used to communicate with the api server. An example for credentials not controlled by Gardener are kubeconfigs or client certificates requested via <code>CertificateSigningRequest</code>s by the shoot owner.</p><p>We propose to use a two step approach to rotate CAs. The start of each phase is triggered by the shoot owner. In summary, the <strong>first phase</strong> is used to create new CAs (for example, the new api server and client CA). Then we make sure that all servers and clients under Gardener&#39;s control trust <em>both</em> old and new CA. Next, we renew all client certificates that are under Gardener&#39;s control so they are now signed by the new CAs. This includes a node rollout in order to propagate the certificates to kubelets and restart all pods. Afterwards, the user needs to change their client credentials to trust both old and new cluster CA. In the <strong>second phase</strong>, we remove all trust to the old CA for servers and clients under Gardener&#39;s control. This does not include a node rollout but all still running pods using <code>ServiceAccount</code>s will continue to trust the old CA until they restart. Also, the user needs to retrieve the new CA bundle to no longer trust the old CA.</p><p>A detailed overview of all steps required for each phase is given in the <a href="/docs/proposals/0018-shoot-ca-rotation/readme/#proposal">proposal</a> section of this GEP.</p><p><em>Introducing a new client CA</em></p><p>Currently, client certificates and the kube-apiserver certificate are signed by the same CA. We propose to create a separate client CA when triggering the rotation. The client CA is used to sign certificates of clients talking to the API Server.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>There are a few reasons for rotating shoot cluster CAs:</p><ul><li>If we have to invalidate client certificates for the kube-apiserver or any other component we are forced to rotate the CA. The only way to invalidate them is to stop trusting all client certificates that are signed by the respective CA, as Kubernetes does not support revoking certificates.</li><li>If the CA itself got leaked.</li><li>If the CA is about to expire.</li><li>If a company policy requires to rotate a CA after a certain point in time.</li></ul><p>In each of those cases we currently need to basically manually recreate and replace all CAs and certificates. The process of rotating by hand is cumbersome and could lead to errors due to the many steps needing to be performed in the right order. By automating the process we want to create a way to securely and easily rotate shoot CAs.</p><h3 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Offer an automated and safe solution to rotate all CAs in a shoot cluster.</li><li>Offer a process that is easily understandable for developers and users.</li><li>Rotate the different CAs in the shoot with a similar process to reduce complexity.</li><li>Add visibility for Shoot owners when the last CA rotation happened.</li></ul><h3 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h3><ul><li>Offer an automated solution for rotating other static credentials (like static token). <ul><li>Later on, a similar two-phase approach could be implemented for the kubeconfig rotation. However, this is out of scope for this enhancement.</li></ul></li><li>Creating a process that runs fully automated without shoot owner interaction. As the shoot owner controls some secrets, that would probably not even be possible.</li><li>Forcing the shoot owner to rotate after a certain time period. Our goal, rather, is to issue long-running certificates and let the user decide depending on their requirements to rotate as needed.</li><li>Configurable default CA lifetime</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>We will add a new feature gate <code>CARotation</code> for <code>gardener-apiserver</code> and <code>gardenlet</code>, which allows to enable or disable the possibility to trigger the rotation.</p><h3 id="triggering-the-ca-rotation" tabindex="-1">Triggering the CA Rotation <a class="header-anchor" href="#triggering-the-ca-rotation" aria-label="Permalink to &quot;Triggering the CA Rotation&quot;">​</a></h3><ul><li>Triggered via <code>gardener.cloud/operation</code> annotation in symmetry with other operations like reconciliation, kubeconfig rotation, etc. <ul><li>Annotation increases the generation</li><li>Value for triggering first phase: <code>start-ca-rotation</code></li><li>Value for triggering the second phase: <code>complete-ca-rotation</code></li><li><code>gardener-apiserver</code> performs the needful validation: a user can&#39;t trigger another rotation if one is already in progress, a user can&#39;t trigger <code>complete-ca-rotation</code> if first phase has not been completed, etc.</li></ul></li><li>The annotation triggers a usual shoot reconciliation (just like a kubeconfig or SSH key rotation).</li><li>The <code>gardenlet</code> begins the CA rotation sequence by setting the new status section <code>.status.credentials.caRotation</code> (probably in <code>updateShootStatusOperationStart</code>) and removes the annotation afterwards. <ul><li>Shoot reconciliation needs to be idempotent to CA rotation phase, i.e., if a usual reconciliation or maintenance operation is triggered in between, no new CAs are generated or similar things that would interfere with the CA rotation sequence.</li></ul></li></ul><h3 id="changing-the-shoot-status" tabindex="-1">Changing the Shoot Status <a class="header-anchor" href="#changing-the-shoot-status" aria-label="Permalink to &quot;Changing the Shoot Status&quot;">​</a></h3><p>A new section in the Shoot status is added when the first rotation is triggered:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  credentials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    rotation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      certificateAuthorities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        phase</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Prepare</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Prepare|Finalize|Completed</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        lastCompletion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2022-02-07T14:23:44Z</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # kubeconfig:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    #   phase:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    #   lastCompletion:</span></span></code></pre></div><p>Later on, this section could be augmented with other information, like the names of the credentials secrets (e.g. <a href="https://github.com/gardener/gardener/issues/1749" target="_blank" rel="noreferrer">gardener/gardener#1749</a>)</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  credentials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    resources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kubeconfig</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Secret</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">shoot-foo.kubeconfig</span></span></code></pre></div><h3 id="rotation-sequence-for-cluster-and-client-ca" tabindex="-1">Rotation Sequence for Cluster and Client CA <a class="header-anchor" href="#rotation-sequence-for-cluster-and-client-ca" aria-label="Permalink to &quot;Rotation Sequence for Cluster and Client CA&quot;">​</a></h3><p>The proposal section includes a detailed description of all steps involved for rotating from a given <code>CA0</code> to the target <code>CA1</code>.</p><p><code>t0</code>: Today&#39;s situation:</p><ul><li><code>kube-apiserver</code> uses SERVER CERT signed by <code>CA0</code> and trusts CLIENT CERTS signed by <code>CA0</code></li><li><code>kube-controller-manager</code> issues new CLIENT CERTS signed by <code>CA0</code></li><li>kubeconfig trusts only <code>CA0</code></li><li><code>ServiceAccount</code> secrets trust only <code>CA0</code></li><li>kubelet uses CLIENT CERT signed by <code>CA0</code></li></ul><p><code>t1</code>: Shoot owner triggers first step of CA rotation process (--&gt; phase one is started):</p><ul><li>Generate <code>CA1</code></li><li>Generate <code>CLIENT_CA1</code></li><li>Update <code>kube-apiserver</code>, <code>kube-scheduler</code>, etc., to trust CLIENT CERTS signed by both <code>CA0</code> and <code>CLIENT_CA1</code> (<code>--client-ca-file</code> flag)</li><li>Update <code>kube-controller-manager</code> to issue new CLIENT CERTS now with <code>CLIENT_CA1</code></li><li>Update kubeconfig so that its CA bundle contains both <code>CA0</code> and<code>CA1</code> (if kubeconfig still contains a legacy CLIENT CERT then rotate the kubeconfig)</li><li>Update <code>generic-token-kubeconfig</code> so that its CA bundle contains both <code>CA0</code> and<code>CA1</code></li><li>Update <code>kube-controller-manager</code> to populate both <code>CA0</code> and <code>CA1</code> in <code>ServiceAccount</code> secrets</li><li>Restart control plane components so that their CA bundle contains both <code>CA0</code> and <code>CA1</code></li><li>Renew CLIENT CERTS (sign them with <code>CLIENT_CA1</code>) for the following control plane components: Prometheus, DWD, legacy VPN), if not dropped already in the context of <a href="https://github.com/gardener/gardener/issues/4661" target="_blank" rel="noreferrer">gardener/gardener#4661</a></li><li>Trigger node rollout <ul><li>This issues new CLIENT CERTS for all kubelets signed by <code>CLIENT_CA1</code></li><li>This restarts all <code>Pod</code>s and propagates <code>CA0</code> and <code>CA1</code> into their mounted <code>ServiceAccount</code> secrets (note CAs can not be reloaded by go client, therefore we need a restart of pods)</li></ul></li><li><em>Ask the user to exchange all their client credentials (kubeconfig, CLIENT CERTS issued by <code>CertificateSigningRequest</code>s) to trust both CA0 and CA1</em></li></ul><p><code>t2</code>: Shoot owner triggers second step of CA rotation process (--&gt; phase two is started):</p><p>Prerequisite: All Gardener-controlled actions listed in <code>t1</code> were executed successfully (for example node rollout). The shoot owner has guaranteed that they exchanged their client credentials and triggered step 2 via an annotation.</p><ul><li>Renew SERVER CERTS (sign them with <code>CA1</code>) for <code>kube-apiserver</code>, <code>kube-controller-manager</code>, <code>cloud-controller-manager</code>, etc.</li><li>Update <code>kube-apiserver</code>, <code>kube-scheduler</code>, etc., to trust only CLIENT CERTS signed by <code>CLIENT_CA1</code></li><li>Update kubeconfig so that its CA bundle contains only <code>CA1</code></li><li>Update <code>generic-token-kubeconfig</code> so that its CA bundle contains only <code>CA1</code></li><li>Update <code>kube-controller-manager</code> to only contain CA1. <code>ServiceAccount</code> secrets created after this point will get secrets that include only <code>CA1</code></li><li>Restart control plane components so that their CA bundle contains only <code>CA1</code></li><li>Restart kubelets so that the CA bundle in their kubeconfigs contain only <code>CA1</code></li><li>Delete <code>CA0</code></li><li><em>Ask the user to optionally restart their <code>Pod</code>s since they still contain <code>CA0</code> in memory in order to eliminate trust to the old cluster CA.</em></li><li><em>Ask the user to exchange all their client credentials (download kubeconfig containing only <code>CA1</code>; when using CLIENT CERTS trust only <code>CA1</code>)</em></li></ul><h3 id="rotation-sequence-of-other-cas" tabindex="-1">Rotation Sequence of Other CAs <a class="header-anchor" href="#rotation-sequence-of-other-cas" aria-label="Permalink to &quot;Rotation Sequence of Other CAs&quot;">​</a></h3><p>Apart from the kube-apiserver CA (and the client CA), we also use 5 other CAs as mentioned above in the Gardener codebase. We propose to rotate those CAs together with the kube-apiserver CA following the same trigger.</p><p>ℹ️ Note for the front-proxy CA: users need to make sure, extension API servers have reloaded the <code>extension-apiserver-authentication</code> ConfigMap, before triggering the second phase.</p><p>You can find Gardener managed CAs listed in <a href="https://github.com/gardener/gardener/blob/04d2b3f459d198e8db0ab57180ca2fea18e84da9/pkg/operation/botanist/wanted_secrets.go#L48" target="_blank" rel="noreferrer">wanted_secrets.go</a>.</p><p>Regarding the rotation steps, we want to follow a similar approach to the one we defined for the kube-apiserver CA. Exemplary, we are going to show the timeline for ETCD_CA but the logic should be similar for all the above listed CAs.</p><ul><li><code>t0</code>: <ul><li>etcd trusts client certificates signed by <code>ETCD_CA0</code> and uses a server certificate signed by <code>ETCD_CA0</code></li><li><code>kube-apiserver</code> and <code>backup-restore</code> use a client certificate signed by <code>ETCD_CA0</code> and trust <code>ETCD_CA0</code></li></ul></li><li><code>t1</code>: <ul><li>Generate <code>ETCD_CA1</code></li><li>Update <code>etcd</code> to trust CLIENT CERTS signed by both <code>ETCD_CA0</code> and <code>ETCD_CA1</code></li><li>Update <code>kube-apiserver</code> and <code>backup-restore</code>: <ul><li>Adapt CA bundle to trust both <code>ETCD_CA0</code> and <code>ETCD_CA1</code></li><li>Renew CLIENT CERTS (sign them with <code>ETCD_CA1</code>)</li></ul></li></ul></li><li><code>t2</code>: <ul><li>Update <code>etcd</code>: <ul><li>Trust only CLIENT CERTS signed by <code>ETCD_CA1</code></li><li>Renew SERVER CERT (sign it with <code>ETCD_CA1</code>)</li></ul></li><li>Update <code>kube-apiserver</code> and <code>backup-restore</code> so that their CA bundle contains only <code>ETCD_CA1</code></li></ul></li></ul><p>ℹ️ This means we are requiring two restarts of etcd in total.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><p>This section presents a different approach to rotate the CAs, which is to <em>temporarily create a second set of api-servers utilizing the new CA</em>. After presenting the approach, advantages and disadvantages of both approaches are listed.</p><p><code>t0</code>: Today&#39;s situation:</p><ul><li><code>kube-apiserver</code> uses SERVER CERT signed by <code>CA0</code> and trusts CLIENT CERTS signed by <code>CA0</code></li><li><code>kube-controller-manager</code> issues new CLIENT CERTS with <code>CA0</code></li><li>kubeconfig contains only <code>CA0</code></li><li><code>ServiceAccount</code> secrets contain only <code>CA0</code></li><li>kubelet uses CLIENT CERT signed by <code>CA0</code></li></ul><p><code>t1</code>: User triggers first step of CA rotation process (--&gt; phase one):</p><ul><li>Generate <code>CA1</code></li><li>Generate <code>CLIENT_CA1</code></li><li>Create new <code>DNSRecord</code>, <code>Service</code>, Istio configuration, etc., for second <code>kube-apiserver</code> deployment</li><li>Deploy second <code>kube-apiserver</code> deployment trusting only CLIENT CERTS signed by <code>CLIENT_CA1</code> and using SERVER CERT signed by <code>CA1</code></li><li>Update <code>kube-scheduler</code>, etc., to trust only CLIENT CERTS signed by <code>CLIENT_CA1</code> (<code>--client-ca-file</code> flag)</li><li>Update <code>kube-controller-manager</code> to issue new CLIENT CERTS with <code>CLIENT_CA1</code></li><li>Update kubeconfig so that it points to the new <code>DNSRecord</code> and its CA bundle contains only <code>CA1</code> (if kubeconfig still contains a legacy CLIENT CERT then rotate the kubeconfig)</li><li>Update <code>ServiceAccount</code> secrets so that their CA bundle contains both <code>CA0</code> and <code>CA1</code></li><li>Restart control plane components so that they point to the second <code>kube-apiserver</code> <code>Service</code> and so that their CA bundle contains only <code>CA1</code></li><li>Renew CLIENT CERTS (sign them with <code>CLIENT_CA1</code>) for control plane components (Prometheus, DWD, legacy VPN) and point them to the second <code>kube-apiserver</code> <code>Service</code></li><li>Adapt <code>apiserver-proxy-pod-mutator</code> to point <code>KUBERNETES_SERVICE_HOST</code> env variable to second <code>kube-apiserver</code></li><li>Trigger node rollout <ul><li>This issues new CLIENT CERTS for all kubelets signed by <code>CLIENT_CA1</code> and points them to the second <code>DNSRecord</code></li><li>This restarts all <code>Pod</code>s and propagates <code>CA0</code> and <code>CA1</code> into their mounted <code>ServiceAccount</code> secrets</li></ul></li><li><em>Ask the user to exchange all their client credentials (kubeconfig, CLIENT CERTS issued by <code>CertificateSigningRequest</code>s)</em></li></ul><p><code>t2</code>: User triggers second step of CA rotation process (--&gt; phase two):</p><ul><li>Update <code>ServiceAccount</code> secrets so that their CA bundle contains only <code>CA1</code></li><li>Update <code>apiserver-proxy</code> to talk to second <code>kube-apiserver</code></li><li>Drop first <code>DNSRecord</code>, <code>Service</code>, Istio configuration and first <code>kube-apiserver</code> deployment</li><li>Drop <code>CA0</code></li><li><em>Ask the user to optionally restart their <code>Pod</code>s since they still contain <code>CA0</code> in memory.</em></li></ul><h4 id="advantages-disadvantages-approach-two-api-servers" tabindex="-1">Advantages/Disadvantages Approach Two API Servers <a class="header-anchor" href="#advantages-disadvantages-approach-two-api-servers" aria-label="Permalink to &quot;Advantages/Disadvantages Approach Two API Servers&quot;">​</a></h4><ul><li>(+) User needs to adapt client credentials only once</li><li>(/) Unstable API server domain</li><li>(-) Probably more implementation effort</li><li>(-) More complex</li><li>(-) CA rotation process does not work similar for all CAs in our system</li></ul><h4 id="advantages-disadvantages-of-currently-preferred-approach-see-proposal" tabindex="-1">Advantages/Disadvantages of Currently Preferred Approach (See Proposal) <a class="header-anchor" href="#advantages-disadvantages-of-currently-preferred-approach-see-proposal" aria-label="Permalink to &quot;Advantages/Disadvantages of Currently Preferred Approach (See Proposal)&quot;">​</a></h4><ul><li>(+) Implementation effort seems &quot;straight-forward&quot;</li><li>(+) CA rotation process works similar for all CAs in our system</li><li>(/) Stable API server domain</li><li>(-) User needs to adapt client credentials twice</li></ul>`,59)]))}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
